{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'threshold' not in case:
        raise ValueError("missing threshold")
    if 'calls' not in case or not isinstance(case['calls'], list):
        raise ValueError("missing or invalid calls")
    threshold = case['threshold']
    calls = case['calls']
    req_fields = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
    for call in calls:
        for f in req_fields:
            if f not in call:
                raise ValueError(f"missing field {f} in call")
        if call.get('prediction_tokens', 0) <= 0:
            raise ValueError("prediction_tokens must be positive")
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        gain = call['loss_without_call'] - call['loss_with_call']
        normalized_gain = gain / call['prediction_tokens']
        accepted = call['parseable'] is True and normalized_gain >= threshold
        diagnostics.append({
            'accepted': accepted,
            'call_id': call['call_id'],
            'normalized_gain': normalized_gain
        })
        if accepted:
            accepted_call_ids.append(call['call_id'])
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"}
